function base(){return {mesas:Array.from({length:12},(_,i)=>({id:i+1,comensales:[],consumosMesa:[],pagos:[],cuentasPendientes:[],ultimaComanda:null})),historial:[]}}
let data=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('restoCobroV1')||'null')||base(); if(!data.historial)data.historial=[]; if(!data.mesas||!data.mesas.length)data.mesas=base().mesas; data.mesas.forEach(m=>{m.pagos=m.pagos||[];m.cuentasPendientes=m.cuentasPendientes||[];if(!('ultimaComanda' in m))m.ultimaComanda=null;(m.consumosMesa||[]).forEach(x=>{x.comandado=Math.min(x.cant,Number(x.comandado||0));x.pagado=Math.min(x.cant,Number(x.pagado||0))});(m.comensales||[]).forEach(c=>(c.consumos||[]).forEach(x=>{x.comandado=Math.min(x.cant,Number(x.comandado||0));x.pagado=Math.min(x.cant,Number(x.pagado||0))}))});
let mesaId=null,destino={tipo:'mesa'}, pagoContexto={label:'MESA COMPLETA',items:[]}, ordenMedios=[]; const $=s=>document.querySelector(s); const money=n=>'$'+Math.round(Number(n||0)).toLocaleString('es-AR'); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(data))} function mesa(){return data.mesas.find(m=>m.id===mesaId)} function suma(a){return (a||[]).reduce((s,x)=>s+x.precio*x.cant,0)} function sumaPendiente(a){return (a||[]).reduce((s,x)=>s+x.precio*Math.max(0,x.cant-Number(x.pagado||0)),0)} function totalMesa(m){return suma(m.consumosMesa)+m.comensales.reduce((s,c)=>s+suma(c.consumos),0)} function senasPorDestino(m){return m.senas||{'mesa':Math.max(0,Number(m.sena||0))}} function senaDestino(m,id){return Math.max(0,Number(senasPorDestino(m)[id]||0))} function senaMesa(m){return Object.values(senasPorDestino(m)).reduce((a,v)=>a+Math.max(0,Number(v||0)),0)} function subtotalDestino(m,id){return id==='mesa'?suma(m.consumosMesa):suma(m.comensales.find(c=>c.id===id)?.consumos||[])} function validarSenas(m){return Object.entries(senasPorDestino(m)).every(([id,v])=>Number(v)<=subtotalDestino(m,id))} function senaDisponibleDestino(m,id){const usada=(m.pagos||[]).reduce((a,p)=>a+(p.senasPorDestino?.[id]||0),0);const reservada=(m.cuentasPendientes||[]).reduce((a,c)=>a+(c.senasPorDestino?.[id]||0),0);return Math.max(0,senaDestino(m,id)-usada-reservada)} function senasDisponibles(m,items){const ids=new Set(items.map(x=>x.ownerId));return Object.fromEntries([...ids].map(id=>[id,senaDisponibleDestino(m,id)]).filter(x=>x[1]>0))} function senaAplicada(m){return (m.pagos||[]).reduce((s,p)=>s+Number(p.sena||0),0)} function senaReservada(m){const ids=new Set();return (m.cuentasPendientes||[]).reduce((s,c)=>{if(c.splitGroupId){if(ids.has(c.splitGroupId))return s;ids.add(c.splitGroupId)}return s+Number(c.sena||0)},0)} function senaDisponible(m){return Object.keys(senasPorDestino(m)).reduce((a,id)=>a+senaDisponibleDestino(m,id),0)} function descuentoMesa(m){return (m.pagos||[]).reduce((s,p)=>s+Number(p.descuento||0),0)} function pagadoBase(m){return (m.pagos||[]).reduce((s,p)=>s+p.base,0)} function recargos(m){return (m.pagos||[]).reduce((s,p)=>s+p.recargo,0)} function pendiente(m){return Math.max(0,totalMesa(m)-pagadoBase(m)-senaMesa(m)-descuentoMesa(m))} function pendienteComensal(c){return sumaPendiente(c.consumos)}
function renderMesas(){mesaId=null;$('#app').innerHTML=`<div class="wrap"><div class="row between top-actions"><div class="row"><button class="primary" onclick="renderHistorial()">HISTORIAL / CIERRE DE CAJA</button><button onclick="administrarMesas()">ADMINISTRAR MESAS</button><button onclick="resetMesas()">REINICIAR MESAS</button></div></div><div class="grid mesa-grid">${data.mesas.map(m=>{const t=totalMesa(m),p=pendiente(m),estado=!t?'libre':(((m.cuentasPendientes||[]).length||pagadoBase(m)>0)&&p>0?'pendiente':'abierta');const txt=estado==='libre'?'LIBRE':estado==='pendiente'?'PENDIENTE':'ABIERTA';return `<div class="mesa ${estado}" onclick="abrir(${m.id})"><h3>MESA ${m.id}</h3><span class="estado">${txt}</span></div>`}).join('')}</div></div>`}
function mesaVacia(m){return totalMesa(m)===0&&pagadoBase(m)===0&&!(m.comensales||[]).length&&!(m.pagos||[]).length}
let mesaAdminSeleccion=null;
function administrarMesas(){
  mesaAdminSeleccion=new Set(data.mesas.map(m=>Number(m.id)));
  const mapa=Array.from({length:26},(_,i)=>{const id=i+1,activa=mesaAdminSeleccion.has(id);return `<button type="button" id="mesaAdmin${id}" class="mesa-mini ${activa?'active':''}" onclick="toggleMesaAdmin(${id})">${id}</button>`}).join('');
  modalHTML('ADMINISTRAR MESAS',`<div class="mesa-admin-grid">${mapa}</div>`,`<button class="primary" onclick="aceptarMesasAdmin()">ACEPTAR</button>`);
}
function toggleMesaAdmin(id){
  const activa=mesaAdminSeleccion.has(id);
  if(activa){
    const m=data.mesas.find(x=>Number(x.id)===id);
    if(m&&!mesaVacia(m)){alert('NO SE PUEDE QUITAR UNA MESA EN USO.');return}
    mesaAdminSeleccion.delete(id);
  }else mesaAdminSeleccion.add(id);
  document.querySelector(`#mesaAdmin${id}`)?.classList.toggle('active',mesaAdminSeleccion.has(id));
}
function aceptarMesasAdmin(){
  const actuales=new Map(data.mesas.map(m=>[Number(m.id),m]));
  data.mesas=[...mesaAdminSeleccion].sort((a,b)=>a-b).map(id=>actuales.get(id)||{id,comensales:[],consumosMesa:[],pagos:[],cuentasPendientes:[],ultimaComanda:null});
  save();cerrarModal();renderMesas();
}
function abrir(id){mesaId=id;destino={tipo:'mesa'};renderMesa()}
function renderMesa(){const m=mesa(),cats=[...new Set(catalogo.map(p=>p.categoria))];const destinoActivo=destino.tipo==='mesa'?'mesa':destino.id;$('#app').innerHTML=`<div class="wrap"><div class="row between"><button onclick="renderMesas()">← MESAS</button><h2>MESA ${m.id}</h2><div><b>SUBTOTAL ${money(totalMesa(m))}</b> · SEÑA − ${money(senaMesa(m))} · PAGADO ${money(pagadoBase(m))} · <b>PENDIENTE ${money(pendiente(m))}</b></div></div><div class="spacer"></div><div class="actions-main"><button class="action-load" onclick="agregarComensal()">AGREGAR COMENSAL</button><button class="action-load" onclick="destino={tipo:'mesa'};renderMesa()">AGREGAR CONSUMO GENERAL</button><button class="action-command" onclick="imprimirComandaNueva()">IMPRIMIR COMANDA${cantidadPendienteComanda(m)?` (${cantidadPendienteComanda(m)})`:''}</button><button class="pay" onclick="mostrarCobro()">COBRAR MESA</button>${m.ultimaComanda?'<button onclick="reimprimirUltimaComanda()">REIMPRIMIR ÚLTIMA COMANDA</button>':''}</div><div class="comensal-tabs"><button class="${destinoActivo==='mesa'?'active':''}" onclick="destino={tipo:'mesa'};renderMesa()">GENERAL</button>${m.comensales.map(c=>`<button class="${destinoActivo===c.id?'active':''}" onclick="seleccionarComensal('${c.id}')">${esc(c.nombre)}</button>`).join('')}</div><div class="grid"><div class="card"><h3>CONSUMO GENERAL</h3>${lista(m.consumosMesa,'mesa')}<b>SUBTOTAL: ${money(suma(m.consumosMesa))}</b></div>${m.comensales.map(c=>`<div class="card"><div class="row between"><h3>${esc(c.nombre)}</h3><button onclick="seleccionarComensal('${c.id}')">CARGAR</button></div>${lista(c.consumos,c.id)}<b>SUBTOTAL: ${money(suma(c.consumos))}</b><div class="spacer"></div><button class="danger" onclick="borrarComensal('${c.id}')">ELIMINAR COMENSAL</button></div>`).join('')}</div>${cats.map(cat=>`<div class="menu-category">${cat.toUpperCase()}</div><div class="grid">${catalogo.filter(p=>p.categoria===cat).map(p=>`<div class="producto" onclick="agregarProducto('${p.id}')"><b>${esc(p.nombre)}</b><div>${money(p.precio)}</div></div>`).join('')}</div>`).join('')}<div class="card manual-card"><h3>PRODUCTO MANUAL</h3><div class="row"><input id="manualNombre" placeholder="DESCRIPCIÓN"><input id="manualPrecio" type="number" min="0" placeholder="PRECIO"><button onclick="agregarManual()">AGREGAR</button></div></div><div class="card manual-card"><h3>AGREGAR SEÑA</h3><div class="row"><select id="destinoSena" onchange="actualizarImporteSena()"><option value="mesa">GENERAL</option>${m.comensales.map(c=>`<option value="${c.id}">${esc(c.nombre)}</option>`).join('')}</select><input id="importeSena" type="number" min="0" step="1" placeholder="IMPORTE DE SEÑA" value="${senaDestino(m,'mesa')||''}"><button onclick="guardarSena()">GUARDAR SEÑA</button></div><div>${Object.entries(senasPorDestino(m)).filter(([id,v])=>Number(v)>0).map(([id,v])=>`<div>SEÑA ${esc(id==='mesa'?'GENERAL':m.comensales.find(c=>c.id===id)?.nombre||'COMENSAL')}: − ${money(v)}</div>`).join('')}</div><div>SUBTOTAL: <b>${money(totalMesa(m))}</b> · SEÑA: <b>− ${money(senaMesa(m))}</b> · TOTAL: <b>${money(Math.max(0,totalMesa(m)-senaMesa(m)))}</b></div></div></div>`}
function target(){const m=mesa();return destino.tipo==='mesa'?m.consumosMesa:(m.comensales.find(c=>c.id===destino.id)?.consumos||m.consumosMesa)}
function agregarComensal(){const n=prompt('Nombre del comensal:');if(!n?.trim())return;const c={id:crypto.randomUUID(),nombre:n.trim(),consumos:[]};mesa().comensales.push(c);destino={tipo:'comensal',id:c.id,nombre:c.nombre};save();renderMesa()}
function seleccionarComensal(id){const c=mesa().comensales.find(x=>x.id===id);destino={tipo:'comensal',id,nombre:c.nombre};renderMesa()}
function modalHTML(titulo,cuerpo,acciones=''){document.body.insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modalBg"><div class="modal"><h3>${titulo}</h3>${cuerpo}<div class="modal-actions">${acciones}<button onclick="cerrarModal()">CANCELAR</button></div></div></div>`)}
function cerrarModal(){document.querySelector('#modalBg')?.remove()}
function elegirOpcion(titulo,opciones,cb){modalHTML(titulo,opciones.map((o,i)=>`<label class="choice"><input type="radio" name="opt" value="${esc(o)}" ${i===0?'checked':''}> ${esc(o)}</label>`).join(''),`<button class="primary" id="okOpt">ACEPTAR</button>`);document.querySelector('#okOpt').onclick=()=>{const v=document.querySelector('input[name=opt]:checked')?.value;cerrarModal();cb(v)}}
function empanadasModal(p){const sabores=['CARNE','JAMÓN Y QUESO','CEBOLLA Y QUESO','POLLO','VERDURA'];modalHTML('ELEGIR EMPANADAS',sabores.map((o,i)=>`<div class="qtyrow"><b>${o}</b><div><button onclick="cambiarQty(${i},-1)">−</button><span id="qty${i}">0</span><button onclick="cambiarQty(${i},1)">+</button></div></div>`).join('')+`<div class="selection-total">TOTAL: <b id="empTotal">0 EMPANADAS · ${money(0)}</b></div>`,`<button class="primary" onclick="confirmarEmpanadas('${p.id}')">AGREGAR</button>`)}
function cambiarQty(i,d){const e=document.querySelector('#qty'+i);e.textContent=Math.max(0,Number(e.textContent)+d);const qs=[...document.querySelectorAll('[id^=qty]')].reduce((s,x)=>s+Number(x.textContent),0);document.querySelector('#empTotal').textContent=`${qs} EMPANADAS · ${money(qs*4500)}`}
function confirmarEmpanadas(id){const p=catalogo.find(x=>x.id===id),sabores=['CARNE','JAMÓN Y QUESO','CEBOLLA Y QUESO','POLLO','VERDURA'],t=target();let total=0;sabores.forEach((sab,i)=>{const q=Number(document.querySelector('#qty'+i).textContent);if(q){total+=q;const nombre=`${p.nombre} — ${sab}`,key=p.id+'|'+nombre,ex=t.find(x=>x.key===key);ex?ex.cant+=q:t.push({...p,nombre,key,cant:q,comandado:0})}});if(!total)return alert('ELEGÍ AL MENOS UNA EMPANADA.');cerrarModal();save();renderMesa()}
const INGREDIENTES_ENSALADA=['LECHUGA','RÚCULA','TOMATE','HUEVO','ZANAHORIA','CHOCLO','CEBOLLA','REMOLACHA'];
function ingredientesChecks(nombre='ingrediente'){return `<div class="ingredient-grid">${INGREDIENTES_ENSALADA.map(i=>`<label class="choice ingredient-choice"><input type="checkbox" name="${nombre}" value="${esc(i)}"> <span>${esc(i)}</span></label>`).join('')}</div>`}
function elegidos(nombre='ingrediente'){return [...document.querySelectorAll(`input[name="${nombre}"]:checked`)].map(x=>x.value)}
function ensaladaModal(p,cb){modalHTML('ELEGIR 3 INGREDIENTES',`${ingredientesChecks('ensBase')}<div class="selection-total">SELECCIONADOS: <b id="ensBaseTotal">0 / 3</b></div>`,`<button class="primary" id="okEnsBase">AGREGAR</button>`);const checks=[...document.querySelectorAll('input[name="ensBase"]')];checks.forEach(ch=>ch.onchange=()=>{const sel=elegidos('ensBase');if(sel.length>3){ch.checked=false;return alert('PODÉS ELEGIR 3 INGREDIENTES.')}document.querySelector('#ensBaseTotal').textContent=`${elegidos('ensBase').length} / 3`});document.querySelector('#okEnsBase').onclick=()=>{const sel=elegidos('ensBase');if(sel.length!==3)return alert('ELEGÍ EXACTAMENTE 3 INGREDIENTES.');cerrarModal();cb(`ENSALADA — ${sel.join(' / ')}`)}}
function guarnicionModal(p,cb){modalHTML('ELEGIR GUARNICIÓN',`<label class="choice"><input type="radio" name="guarnicion" value="PAPAS FRITAS" checked> <span>PAPAS FRITAS</span></label><label class="choice"><input type="radio" name="guarnicion" value="ENSALADA"> <span>ENSALADA</span></label><div id="guarnEns" class="conditional-box" style="display:none"><b>ELEGÍ HASTA 3 INGREDIENTES</b>${ingredientesChecks('guarnIng')}<div class="selection-total">SELECCIONADOS: <b id="guarnTotal">0 / 3</b></div></div>`,`<button class="primary" id="okGuarn">AGREGAR</button>`);document.querySelectorAll('input[name="guarnicion"]').forEach(r=>r.onchange=()=>{document.querySelector('#guarnEns').style.display=r.value==='ENSALADA'&&r.checked?'block':'none'});const checks=[...document.querySelectorAll('input[name="guarnIng"]')];checks.forEach(ch=>ch.onchange=()=>{const sel=elegidos('guarnIng');if(sel.length>3){ch.checked=false;return alert('PODÉS ELEGIR HASTA 3 INGREDIENTES.')}document.querySelector('#guarnTotal').textContent=`${elegidos('guarnIng').length} / 3`});document.querySelector('#okGuarn').onclick=()=>{const g=document.querySelector('input[name="guarnicion"]:checked')?.value;if(g==='ENSALADA'){const sel=elegidos('guarnIng');if(!sel.length)return alert('ELEGÍ AL MENOS 1 INGREDIENTE PARA LA ENSALADA.');cerrarModal();return cb(`${p.nombre} — ENSALADA — ${sel.join(' / ')}`)}cerrarModal();cb(`${p.nombre} — PAPAS FRITAS`)}}
function ingredienteAdicionalModal(p){
  modalHTML('INGREDIENTE ADICIONAL',
    `<div class="qtyrow"><b>CANTIDAD DE INGREDIENTES</b><div><button id="menosExtra">−</button><span id="qtyExtra">0</span><button id="masExtra">+</button></div></div>
     <div id="extraOpciones" class="conditional-box" style="display:none"><b>ELEGÍ LOS INGREDIENTES</b>${ingredientesChecks('extraIng')}<div class="selection-total">SELECCIONADOS: <b id="extraSel">0</b></div></div>
     <div class="selection-total">TOTAL: <b id="extraPrecio">${money(0)}</b></div>`,
    `<button class="primary" id="okExtra">AGREGAR</button>`
  );
  let q=0;
  const pintar=()=>{
    document.querySelector('#qtyExtra').textContent=q;
    document.querySelector('#extraPrecio').textContent=money(q*p.precio);
    document.querySelector('#extraOpciones').style.display=q?'block':'none';
    document.querySelector('#extraSel').textContent=`${elegidos('extraIng').length} / ${q}`;
    document.querySelectorAll('input[name="extraIng"]').forEach(x=>x.disabled=!q);
  };
  document.querySelector('#masExtra').onclick=()=>{q++;pintar()};
  document.querySelector('#menosExtra').onclick=()=>{
    q=Math.max(0,q-1);
    const marcados=[...document.querySelectorAll('input[name="extraIng"]:checked')];
    if(marcados.length>q)marcados.forEach((x,i)=>{if(i>=q)x.checked=false});
    pintar();
  };
  document.querySelectorAll('input[name="extraIng"]').forEach(ch=>ch.onchange=()=>{
    const sel=elegidos('extraIng');
    if(sel.length>q){ch.checked=false;alert(`ELEGISTE ${q} INGREDIENTE${q===1?'':'S'} ADICIONAL${q===1?'':'ES'}.`)}
    pintar();
  });
  document.querySelector('#okExtra').onclick=()=>{
    if(q<1)return alert('ELEGÍ LA CANTIDAD DE INGREDIENTES ADICIONALES CON +.');
    const sel=elegidos('extraIng');
    if(sel.length!==q)return alert(`ELEGÍ EXACTAMENTE ${q} INGREDIENTE${q===1?'':'S'}.`);
    const nombre=`${p.nombre} × ${q} — ${sel.join(' / ')}`;
    const precio=p.precio*q,t=target(),key=p.id+'|'+nombre,ex=t.find(x=>x.key===key);
    ex?ex.cant++:t.push({...p,nombre,precio,key,cant:1,comandado:0});
    cerrarModal();save();renderMesa();
  };
  pintar();
}
function personalizar(p,cb){if(p.nombre.toLowerCase().includes('con guarnición'))return guarnicionModal(p,cb);if(p.tipo==='hamb')return elegirOpcion('TIPO DE HAMBURGUESA',['CARNE','VEGGIE'],v=>cb(`${p.nombre} — ${v}`));if(p.tipo==='pizzanesa')return elegirOpcion('TIPO DE PIZZANESA',['CARNE','POLLO'],v=>cb(`${p.nombre} — ${v}`));if(p.tipo==='ensalada')return ensaladaModal(p,cb);if(p.tipo==='postre')return elegirOpcion('ADICIONAL',['DULCE','CREMA'],v=>cb(`${p.nombre} — ${v}`));if(p.tipo==='trago')return elegirOpcion('ELEGIR TRAGO',['FERNET','CAMPARI','GANCIA','GIN','CYNAR','APEROL','VODKA'],v=>cb(`TRAGOS — ${v}`));cb(p.nombre)}
function nombreMitadComanda(p,prefijo){
  const d=datosCon(p);if(!d)return Promise.resolve(`${prefijo} ${p.nombre.replace(/^(Pizza|Pizzanesa) /i,'').toUpperCase()}`);
  return new Promise(resolve=>personalizarIngredientesCon(p,p.nombre,nombreCocina=>resolve(`${prefijo} ${nombreCocina.replace(/^(Pizza|Pizzanesa) /i,'').toUpperCase()}`),p.nombre));
}
async function personalizarMitadesParaComanda(ps,prefijo){
  const nombres=[];
  for(const p of ps)nombres.push(await nombreMitadComanda(p,prefijo));
  return nombres.join(' + ');
}
