const categoriasConPersonalizable=new Set(['Entradas','Hamburguesas','Papas fritas','Pizzanesas','Pizzas']);
function datosCon(p){
  if(!categoriasConPersonalizable.has(p.categoria))return null;
  const m=String(p.nombre||'').match(/^(.*?)\s+con\s+(.+)$/i);if(!m)return null;
  const ingredientes=m[2].split(/\s*,\s*|\s+y\s+/i).map(x=>x.trim()).filter(Boolean);
  return ingredientes.length?{base:m[1].trim(),ingredientes}:null;
}
function personalizarIngredientesCon(p,nombreComercial,cb,etiquetaMitad=''){
  const d=datosCon(p);if(!d)return cb(nombreComercial);
  const sufijo=String(nombreComercial).startsWith(p.nombre)?String(nombreComercial).slice(p.nombre.length):'';
  const contexto=etiquetaMitad?`<div class="selection-total"><b>${esc(etiquetaMitad.toUpperCase())}</b><br>DESTILDÁ LO QUE NO LLEVA</div>`:`<div class="selection-total">DESTILDÁ LO QUE NO LLEVA</div>`;
  modalHTML('¿QUÉ LLEVA?',`<div class="checklist">${d.ingredientes.map((ing,i)=>`<label class="choice"><input type="checkbox" name="ingredienteCon" value="${esc(ing)}" checked> <span>${esc(ing.toUpperCase())}</span></label>`).join('')}</div>${contexto}`,`<button class="primary" id="okIngredientesCon">AGREGAR</button>`);
  document.querySelector('#okIngredientesCon').onclick=()=>{const elegidos=[...document.querySelectorAll('input[name="ingredienteCon"]:checked')].map(x=>x.value);let nombreComanda=d.base;if(elegidos.length===1)nombreComanda+=` con ${elegidos[0]}`;else if(elegidos.length>1)nombreComanda+=` con ${elegidos.slice(0,-1).join(', ')} y ${elegidos[elegidos.length-1]}`;nombreComanda+=sufijo;cerrarModal();cb(nombreComanda)};
}
function agregarProducto(id){const p=catalogo.find(x=>x.id===id);if(p.tipo==='pizza-mitad')return pizzaMitadModal();if(p.tipo==='pizzanesa-mitad')return pizzanesaMitadModal();if(p.tipo==='empanada')return empanadasModal(p);if(p.id==='ens-ad')return ingredienteAdicionalModal(p);personalizar(p,nombre=>{personalizarIngredientesCon(p,nombre,nombreComanda=>{const t=target(),key=p.id+'|'+nombre+'|COMANDA:'+nombreComanda,ex=t.find(x=>x.key===key);ex?ex.cant++:t.push({...p,nombre,nombreComanda,key,cant:1,comandado:0});save();renderMesa()})})}
let manualPendiente=null;
function agregarManual(){const n=$('#manualNombre').value.trim(),p=Number($('#manualPrecio').value);if(!n||p<0||!Number.isFinite(p))return alert('Completá descripción y precio.');manualPendiente={nombre:n,precio:p,cant:1};modalHTML('CANTIDAD',`<div class="qtyrow"><b>${esc(n)} · ${money(p)}</b><div><button onclick="cambiarCantidadManual(-1)">−</button><span id="manualCant">1</span><button onclick="cambiarCantidadManual(1)">+</button></div></div><div class="selection-total">TOTAL: <b id="manualTotal">${money(p)}</b></div>`,`<button class="primary" onclick="confirmarManual()">CONFIRMAR</button>`)}
function cambiarCantidadManual(d){if(!manualPendiente)return;manualPendiente.cant=Math.max(1,manualPendiente.cant+d);document.querySelector('#manualCant').textContent=manualPendiente.cant;document.querySelector('#manualTotal').textContent=money(manualPendiente.precio*manualPendiente.cant)}
function confirmarManual(){if(!manualPendiente)return;const {nombre,precio,cant}=manualPendiente;target().push({id:'manual-'+crypto.randomUUID(),nombre,precio,categoria:'Manual',cant,comandado:0});manualPendiente=null;save();cerrarModal();renderMesa()}
function lista(items,owner){return !items.length?'<p class="muted">Sin consumos.</p>':items.map((x,i)=>`<div class="item row between"><span>${x.cant} × ${esc(x.nombre)} · ${money(x.precio*x.cant)} ${(x.cant-Number(x.comandado||0))>0?`<small class="badge">${x.cant-Number(x.comandado||0)} NUEVO/S</small>`:''}</span><span><button onclick="cambiar('${owner}',${i},-1)">−</button> <button onclick="cambiar('${owner}',${i},1)">+</button> <button onclick="quitar('${owner}',${i})">×</button></span></div>`).join('')}
function ownerItems(o){return o==='mesa'?mesa().consumosMesa:mesa().comensales.find(c=>c.id===o).consumos} function cambiar(o,i,d){const a=ownerItems(o);a[i].cant+=d;if(a[i].cant<=0)a.splice(i,1);else a[i].comandado=Math.min(Number(a[i].comandado||0),a[i].cant);save();renderMesa()} function quitar(o,i){ownerItems(o).splice(i,1);save();renderMesa()} function borrarComensal(id){if(!confirm('¿Eliminar este comensal y sus consumos?'))return;mesa().comensales=mesa().comensales.filter(c=>c.id!==id);destino={tipo:'mesa'};save();renderMesa()}

const CATEGORIAS_SIN_COMANDA=new Set(['bebidas','tragos','cafetería','cafeteria','vinos']);
function itemsPendientesComanda(m){
  const out=[];
  const add=(owner,items)=>{(items||[]).forEach(x=>{if(CATEGORIAS_SIN_COMANDA.has(String(x.categoria||catalogo.find(p=>p.id===x.id)?.categoria||'').trim().toLocaleLowerCase('es-AR')))return;const enviados=Number(x.comandado||0),n=Math.max(0,x.cant-enviados);if(n)out.push({owner,nombre:x.nombreComanda||x.nombre,cant:n,ref:x})})};
  add('GENERAL',m.consumosMesa);(m.comensales||[]).forEach(c=>add(c.nombre,c.consumos));return out;
}
function cantidadPendienteComanda(m){return itemsPendientesComanda(m).reduce((s,x)=>s+x.cant,0)}
function abrirImpresionComanda(comanda,reimpresion=false){
  const w=window.open('','_blank','width=420,height=700');if(!w){alert('EL NAVEGADOR BLOQUEÓ LA VENTANA DE IMPRESIÓN. HABILITÁ LAS VENTANAS EMERGENTES E INTENTÁ DE NUEVO.');return false}
  const d=new Date(comanda.fechaISO);
  w.document.write(`<!doctype html><html><head><title>COMANDA MESA ${comanda.mesa}</title><style>@page{size:80mm auto;margin:3mm}*{box-sizing:border-box}html,body{width:74mm;max-width:74mm;margin:0;padding:0}body{font-family:Consolas,"Courier New",monospace;font-size:13px;line-height:1.25;font-weight:600;text-transform:uppercase;color:#000;overflow-wrap:anywhere;word-break:normal}.c{text-align:center}.line{border-top:1px dashed #000;margin:6px 0}.grupo{font-size:20.67px;line-height:1.25;font-weight:700;margin-top:8px}.prod{font-size:20.67px;line-height:1.25;font-weight:600;margin:3px 0;white-space:normal;overflow-wrap:anywhere}b{font-weight:700}</style></head><body>${reimpresion?'<div class="c"><b>*** REIMPRESIÓN ***</b></div>':''}<div class="c"><b style="font-size:20px">MESA ${comanda.mesa}</b><br><b>${d.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})} HS</b><br>${d.toLocaleDateString('es-AR')}</div><div class="line"></div>${(()=>{const grupos=[];for(const x of comanda.items){let g=grupos.find(y=>y.owner===x.owner);if(!g){g={owner:x.owner,items:[]};grupos.push(g)}g.items.push(x)}return grupos.map(g=>`<div class="grupo">${esc(g.owner)}</div>${g.items.map(x=>`<div class="prod">${x.cant} × ${esc(nombreImpresion(x.nombre))}</div>`).join('')}`).join('')})()}<div class="line"></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();return true
}
function imprimirComandaNueva(){
  const m=mesa(),pend=itemsPendientesComanda(m);if(!pend.length)return alert('NO HAY CONSUMOS NUEVOS PARA ENVIAR A COMANDA.');
  const resumen=pend.map(x=>`${x.owner}: ${x.cant} × ${x.nombre}`).join('\n');
  if(!confirm(`SE VA A IMPRIMIR ESTA COMANDA:\n\n${resumen}\n\n¿CONTINUAR?`))return;
  const comanda={id:crypto.randomUUID(),mesa:m.id,fechaISO:new Date().toISOString(),items:pend.map(x=>({owner:x.owner,nombre:x.nombre,cant:x.cant}))};
  if(!abrirImpresionComanda(comanda,false))return;
  pend.forEach(x=>x.ref.comandado=Number(x.ref.comandado||0)+x.cant);
  // Las bebidas y demás categorías excluidas también dejan de ser NUEVAS
  // al enviar la comanda, aunque no se impriman en cocina.
  const marcarExcluidos=items=>{for(const x of (items||[])){
    const categoria=String(x.categoria||catalogo.find(p=>p.id===x.id)?.categoria||'').trim().toLocaleLowerCase('es-AR');
    if(CATEGORIAS_SIN_COMANDA.has(categoria))x.comandado=x.cant;
  }};
  marcarExcluidos(m.consumosMesa);
  for(const c of (m.comensales||[]))marcarExcluidos(c.consumos);
  m.ultimaComanda=structuredClone(comanda);save();renderMesa();
}
function reimprimirUltimaComanda(){const m=mesa();if(!m.ultimaComanda)return alert('TODAVÍA NO HAY UNA COMANDA PARA REIMPRIMIR.');abrirImpresionComanda(m.ultimaComanda,true)}

function unidadesReservadas(m){const r={},grupos=new Set();for(const c of (m.cuentasPendientes||[])){if(c.splitGroupId){if(grupos.has(c.splitGroupId))continue;grupos.add(c.splitGroupId)}for(const it of (c.items||[])){const k=`${it.ownerId}|||${it.refKey}`;r[k]=(r[k]||0)+1}}return r}
function pendingUnits(m){const out=[],reservadas=unidadesReservadas(m);const add=(owner,ownerId,x)=>{const k=`${ownerId}|||${x.key||x.id||x.nombre}`;const left=Math.max(0,x.cant-Number(x.pagado||0)-Number(reservadas[k]||0));for(let q=0;q<left;q++)out.push({label:`${owner} · ${x.nombre}`,precio:x.precio,ownerId,refKey:x.key||x.id||x.nombre,ref:x})};(m.consumosMesa||[]).forEach(x=>add('GENERAL','mesa',x));m.comensales.forEach(c=>(c.consumos||[]).forEach(x=>add(c.nombre,c.id,x)));return out}
