function cerrarMesa(){const m=mesa(),total=totalMesa(m);if(!total)return alert('La mesa no tiene consumos para cerrar.');if(senaMesa(m)===total&&!m.pagos.length&&!m.cuentasPendientes.length){for(const it of m.consumosMesa)it.pagado=it.cant;for(const c of m.comensales)for(const it of c.consumos)it.pagado=it.cant}if(pendiente(m)>0)return alert(`Todavía quedan ${money(pendiente(m))} pendientes. La mesa solo puede cerrarse cuando el pendiente llegue a $0.`);if(!validarSenas(m))return alert('LA SEÑA NO PUEDE SUPERAR EL SUBTOTAL DE LA CUENTA ASIGNADA.');if(!confirm(`¿Cerrar MESA ${m.id}?\nSubtotal: ${money(total)}\nSeña: - ${money(senaMesa(m))}\nTotal cobrado: ${money(total-senaMesa(m)-descuentoMesa(m)+recargos(m))}`))return;const propinas=(m.pagos||[]).reduce((s,p)=>s+Number(p.propina||0),0);data.historial.unshift({id:crypto.randomUUID(),mesa:m.id,fechaISO:new Date().toISOString(),consumosMesa:structuredClone(m.consumosMesa),comensales:structuredClone(m.comensales),pagos:structuredClone(m.pagos),sena:senaMesa(m),descuento:descuentoMesa(m),senas:structuredClone(senasPorDestino(m)),total,recargos:recargos(m),propinas,totalCobrado:total-senaMesa(m)-descuentoMesa(m)+recargos(m)+propinas});const id=m.id;const idx=data.mesas.findIndex(x=>x.id===id);if(idx>=0)data.mesas[idx]={id,comensales:[],consumosMesa:[],pagos:[],cuentasPendientes:[],ultimaComanda:null};save();renderMesas()}
function fechaHora(i){return new Date(i).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'})} function detalleHistorial(x){const filas=a=>(a||[]).map(i=>`<div class="item">${i.cant} × ${esc(i.nombre)} · ${money(i.precio*i.cant)}</div>`).join('')||'<p class="muted">Sin consumos.</p>';return `<div class="detail"><h4>CONSUMO GENERAL · ${money(suma(x.consumosMesa||[]))}</h4>${filas(x.consumosMesa)}${(x.comensales||[]).map(c=>`<h4>${esc(c.nombre)} · ${money(suma(c.consumos||[]))}</h4>${filas(c.consumos)}`).join('')}<h4>SUBTOTAL: ${money(x.total||0)} · SEÑA: − ${money(x.sena||0)} · DESCUENTOS: − ${money(x.descuento||0)} · TOTAL: ${money((x.total||0)-(x.sena||0)-(x.descuento||0))}</h4><h4>PAGOS</h4>${(x.pagos||[]).map(p=>`<div>${p.medio}: ${money(p.base)}${p.recargo?` + ${money(p.recargo)} recargo`:''}${p.propina?` + ${money(p.propina)} propina`:''} = ${money(p.cobrado)}</div>`).join('')}</div>`}
function renderHistorial(){mesaId=null;const h=data.historial||[];$('#app').innerHTML=`<div class="wrap"><div class="row between"><div><button onclick="renderMesas()">← Mesas</button><h2>HISTORIAL / CIERRE DE CAJA</h2></div></div><div class="row"><button class="primary" onclick="descargarHistorialPDF()">DESCARGAR HISTORIAL EN PDF</button><button class="danger" onclick="borrarHistorial()">Borrar historial</button></div><div class="history">${h.length?h.map(x=>`<div class="card"><div class="row between"><div><h3>MESA ${x.mesa}</h3><div class="muted">${fechaHora(x.fechaISO)}</div></div></div><details><summary>Ver detalle</summary>${detalleHistorial(x)}<div class="spacer"></div>${(x.pagos||[]).map(p=>`<button onclick="reimprimirHistorial('${x.id}','${p.id}')">REIMPRIMIR ${esc(p.label||'TICKET')}</button>`).join(' ')}</details></div>`).join(''):'<div class="card">Todavía no hay mesas cerradas.</div>'}</div></div>`}
function reimprimirHistorial(hid,pid){const h=data.historial.find(x=>x.id===hid),p=h?.pagos.find(x=>x.id===pid);if(!p)return;const old=mesaId;mesaId=h.mesa;imprimirTicket(pid);mesaId=old}
function pdfEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[^\x20-\x7E]/g,c=>({Á:'A',É:'E',Í:'I',Ó:'O',Ú:'U',Ñ:'N','á':'a','é':'e','í':'i','ó':'o','ú':'u','ñ':'n','¿':'','¡':''}[c]||''))}
function descargarHistorialPDF(){
  const h=(data.historial||[]).slice().reverse();
  if(!h.length)return alert('NO HAY OPERACIONES PARA DESCARGAR.');
  const now=new Date();
  let gran=0;
  const nombrePago=p=>{
    const l=String(p.label||'').trim();
    if(l&&l!=='PAGO'&&l!=='TOTAL DE LA CUENTA'&&l!=='MESA COMPLETA'&&l!=='CONSUMOS SELECCIONADOS'&&!/^\d+\/\d+$/i.test(l)||/^1 DE \d+ PARTES$/i.test(l))return l;
    const owners=[...new Set((p.items||[]).map(it=>String(it.label||'').split(' · ')[0].trim()).filter(x=>x&&x!=='GENERAL'))];
    return owners.length===1?owners[0]:'';
  };
  const bloques=h.map(x=>{
    const d=new Date(x.fechaISO),ps=x.pagos||[];
    gran+=Number(x.totalCobrado??(Number(x.total||0)-Number(x.sena||0)-Number(x.descuento||0)));
    let filas='';
    ps.forEach(p=>{
      const nombre=nombrePago(p);
      const medios=p.medios?.length?p.medios:[{medio:p.medio,base:p.base}];
      medios.forEach((a,i)=>{
        const importe=Number(a.base||0)+(a.medio==='CRÉDITO'?Number(a.base||0)*.10:0);
        filas+=`<div class="pago-row"><span class="persona">${i===0&&nombre?esc(nombre):''}</span><b class="monto">${money(importe)}</b><span class="medio">${esc(a.medio||'')}</span></div>`;
      });
      if(Number(p.propina||0)>0)filas+=`<div class="pago-row propina-row"><span class="persona"></span><b class="monto">${money(p.propina)}</b><span class="medio">PROPINA</span></div>`;
    });
    if(Number(x.descuento||0)>0)filas+=`<div class="pago-row"><span class="persona">DESCUENTO APLICADO</span><b class="monto">− ${money(x.descuento)}</b><span class="medio">DESCUENTO</span></div>`;
    if(Number(x.sena||0)>0)filas+=`<div class="pago-row"><span class="persona">SUBTOTAL ${money(x.total)}</span><b class="monto">− ${money(x.sena)}</b><span class="medio">SEÑA</span></div>`;
    return `<section><div class="mesa-title">MESA ${x.mesa}</div><div class="hora">${d.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})} HS</div><div class="pagos">${filas}</div></section>`;
  }).join('');
  const w=window.open('','_blank','width=800,height=900');
  const logoURL=new URL('logo-boedo.png',document.baseURI).href;
  w.document.write(`<!doctype html><html><head><title></title><style>
  @page{size:A4 portrait;margin:0}
  html,body{margin:0;padding:0}
  body{padding:15mm}
  *{box-sizing:border-box}
  body{font-family:"Courier New",monospace;color:#000;background:#fff;text-transform:uppercase;font-size:12px;margin:0}
  .logo{text-align:center;margin:0 0 12px}.logo img{width:220px;max-height:90px;object-fit:contain}
  .titulo{text-align:center;font-size:15px;font-weight:700;margin:0 0 10px}
  .meta{text-align:center;margin-bottom:18px;line-height:1.6;font-weight:700}
  section{padding:13px 0;border-top:1px dashed #000;break-inside:avoid}
  .mesa-title{text-align:center;font-size:14px;font-weight:700}
  .hora{text-align:center;margin:3px 0 9px;font-weight:700}
  .pagos{width:100%}
  .pago-row{display:grid;grid-template-columns:1fr 32mm 42mm;column-gap:8mm;align-items:baseline;padding:3px 8mm}
  .persona{text-align:left}.monto{text-align:right;white-space:nowrap}.medio{text-align:left;font-weight:700}
  .gran{border-top:2px solid #000;margin-top:16px;padding-top:12px;font-size:14px;font-weight:700;display:flex;justify-content:space-between}
  </style></head><body><div class="logo"><img src="${logoURL}" alt="BOEDO Y MÁS ALLÁ"></div><div class="titulo">HISTORIAL DE VENTAS</div><div class="meta">${now.toLocaleDateString('es-AR')}<br>CIERRE: ${now.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})} HS</div>${bloques}<div class="gran"><span>TOTAL DEL CIERRE</span><span>${money(gran)}</span></div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);
  w.document.close();
}
function borrarHistorial(){if(!data.historial.length)return alert('El historial ya está vacío.');if(confirm('¿Borrar TODO el historial? Esta acción no se puede deshacer.')&&confirm('Última confirmación: ¿seguro?')){data.historial=[];save();renderHistorial()}} function resetMesas(){if(confirm(`¿REINICIAR LAS ${data.mesas.length} MESAS ABIERTAS? EL HISTORIAL NO SE BORRARÁ.`)){data.mesas=data.mesas.map(m=>({id:m.id,comensales:[],consumosMesa:[],pagos:[],cuentasPendientes:[],ultimaComanda:null}));save();renderMesas()}}
renderMesas();
